system_prompt.output_structure:
Generate a JSON response with this exact structure:

```json
{
  "schemaVersion": "1.0",
  "generatedAt": "[ISO timestamp]",
  "meta": {
    "teamName": "[Extract from data or generate]",
    "sprintName": "[Sprint name]",
    "teamIcon": "[Unicode emoji]",
    "deliveryConfidence": {
      "label": "Delivery Confidence: [0-100]%",
      "color": "[hex color based on confidence]",
      "icon": "[status emoji]"
    },
    "today": {
      "iso": "[current date]",
      "pretty": "[formatted date with sprint progress]"
    },
    "overallSummary": {
      "html": "[Executive summary with actionable insights]",
      "expandCardId": "[ID of card to expand]"
    },
    "priorityCardId": "[highest priority insight card ID]",
    "sprintEndDate": {
      "iso": "[sprint end date]",
      "pretty": "[formatted end date]"
    }
  },
  "kpi": {
    "storyPoints": {
      "done": [completed points],
      "total": [total points],
      "action": {"type": "group", "field": "story_points"}
    },
    "scopeChange": {
      "percent": [scope change percentage],
      "action": {"type": "filter", "field": "scope_change_percent", "operator": "<", "value": 10}
    },
    "ticketHygiene": {
      "percent": [hygiene score],
      "action": {"type": "filter", "field": "Type", "operator": "in", "value": ["Story", "Task"]}
    },
    "sprintProgress": {
      "percent": [time-based progress]
    }
  },
  "insights": [
    {
      "id": "[unique card ID]",
      "priority": [1-6, 1 being highest],
      "header": {
        "title": "[Card Title]",
        "summary": "[Brief insight summary]",
        "icon": "[relevant emoji]",
        "color": "[hex color for urgency]"
      },
      "body": "[HTML content with PrimeNG classes and action buttons]"
    }
  ],
  "table": {
    "dataTree": true,
    "columns": [
      {"title": "Date", "field": "date", "hozAlign": "left"},
      {"title": "Issue ID", "field": "issue_id", "formatter": "link"},
      {"title": "Type", "field": "issue_type"},
      {"title": "Summary", "field": "summary", "widthGrow": 2},
      {"title": "Story Points", "field": "story_points", "hozAlign": "right"},
      {"title": "Assignee", "field": "assignee"},
      {"title": "Status", "field": "status"}
    ],
    "data": "[Transform input data into table rows with _children for hierarchical data]"
  }
}
```
